import random
import math
from fractions import Fraction

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        pivot = matrix[i][i]
        if pivot == 0:
            continue

        for j in range(i, n+1):
            matrix[i][j] /= pivot

        for j in range(n):
            if j != i:
                factor = matrix[j][i]
                for k in range(i, n+1):
                    matrix[j][k] -= factor * matrix[i][k]
    return matrix

def is_solution(matrix, solution):
    n = len(solution)
    m = len(matrix)
    for i in range(m):
        value = sum(matrix[i][j] * solution[j] for j in range(n))
        if not math.isclose(value, 0, abs_tol=1e-9):
            return False
    return True

def generate_cnf_formula(num_vars, num_clauses):
    clauses = []
    for _ in range(num_clauses):
        clause = set()
        while len(clause) < 3:
            var = random.randint(1, num_vars)
            if random.choice([True, False]):
                clause.add(-var)
            else:
                clause.add(var)
        clauses.append(tuple(sorted(clause)))
    return clauses

def generate_diophantine_matrix(cnf_formula):
    n = len(cnf_formula)
    m = sum(len(clause) for clause in cnf_formula)
    matrix = [[0] * (n + 1) for _ in range(m)]

    row = 0
    for i, clause in enumerate(cnf_formula):
        for var in clause:
            if var > 0:
                matrix[row][var - 1] += 1
            else:
                matrix[row][-var - 1] -= 1
        matrix[row][n] = 1
        row += 1

    return matrix

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n_max = 0
    instances_tested = 0
    total_size = 0

    for num_vars in [5, 10, 15, 20, 30, 40]:
